const Reveal={cancel:null};
function gAnim(res,nAgain){if(Reveal.cancel)Reveal.cancel();const o=$('gani'),focus=document.activeElement,reduce=matchMedia('(prefers-reduced-motion: reduce)').matches;let finished=false,timer=null;const exit=()=>{cancel();o.hidden=true;if(focus&&focus.isConnected)focus.focus({preventScroll:true})},cancel=()=>{clearTimeout(timer);removeEventListener('keydown',keys,true);Reveal.cancel=null},finish=()=>{if(finished)return;finished=true;clearTimeout(timer);$('reveal-stage').hidden=true;$('reveal-grid').hidden=false;$('reveal-actions').hidden=false;$('reveal-skip').textContent='結果已保存';$('reveal-skip').disabled=true;$('reveal-exit').focus();SFX.loot()},keys=e=>{if(o.hidden)return;if(e.code==='Escape'){e.preventDefault();e.stopImmediatePropagation();finished?exit():finish()}else if((e.code==='Enter'||e.code==='Space')&&!e.target.closest('button')){e.preventDefault();e.stopImmediatePropagation();finish()}};Reveal.cancel=cancel;o.hidden=false;o.setAttribute('role','dialog');o.setAttribute('aria-label','幸運轉蛋結果');o.innerHTML=`<div class="reveal-shell"><header class="reveal-top"><div><small>LUCKY DRAW / ADVENTURE ISLAND</small><h2>${res.some(r=>r.rare===2)?'好運，真的來了。':'新的收藏，新的可能。'}</h2></div><button class="quiet" id="reveal-skip">跳過演出</button></header><p class="reveal-caption">本次獎勵已保存。跳過與關閉不會再次發獎。</p><div class="capsule-stage" id="reveal-stage"><div class="capsule"></div></div><div class="reveal-grid" id="reveal-grid" hidden>${res.map((r,i)=>{const icon=/寵物/.test(r.t)?'star':/神獸/.test(r.t)?'shield':/裝備|〔/.test(r.t)?'sword':/碎片/.test(r.t)?'dust':'coin';const receipt=RUI.drops.find(d=>r.t.includes(d.n));return `<article class="reveal-card ${r.rare?'rare':''}" style="--rarity:${r.c};animation-delay:${Math.min(i,10)*.035}s">${RUI.icon(icon,45)}<b>${esc(r.t)}</b><small>${receipt?receipt.result:r.rare?'稀有獎勵':'已保存至帳號'}</small></article>`}).join('')}</div><div class="reveal-actions" id="reveal-actions" hidden>${nAgain?`<button class="primary" id="reveal-again">再抽 ${nAgain} 次 →</button>`:''}<button class="quiet" id="reveal-exit">返回冒險</button></div></div>`;$('reveal-skip').onclick=finish;$('reveal-exit').onclick=exit;if($('reveal-again'))$('reveal-again').onclick=()=>{cancel();o.hidden=true;doGacha(nAgain)};addEventListener('keydown',keys,true);$('reveal-skip').focus();if(reduce)finish();else timer=setTimeout(finish,1200)}
function showModal(o){const previous=document.activeElement;stopHold();holdStop();$('ic').textContent=o.ic;$('mh').textContent=o.h;$('msub').textContent=o.sub||'';$('gs').innerHTML=(o.g||[]).map(([v,l])=>`<div><b>${v}</b><small>${l}</small></div>`).join('');$('rec').innerHTML=o.note||'';const btns=$('btns');btns.innerHTML='';for(const [label,action,primary]of o.btns){const b=document.createElement('button');b.textContent=label;if(primary)b.className='pri';b.onclick=()=>{$('ov').classList.remove('show');if(previous?.isConnected)previous.focus({preventScroll:true});action&&action()};btns.append(b)}$('card').setAttribute('role','dialog');$('card').setAttribute('aria-modal','true');$('card').setAttribute('aria-labelledby','mh');$('ov').classList.add('show');setTimeout(()=>btns.querySelector('button')?.focus(),0)}
